1640	func CreateCommit(repo *git.Repository, treeHash, parentHash plumbing.Hash, message, authorName, authorEmail string) (plumbing.Hash, error) {
1641		now := time.Now()
1642		sig := object.Signature{
1643			Name:  authorName,
1644			Email: authorEmail,
1645			When:  now,
1646		}
1647	
1648		commit := &object.Commit{
1649			TreeHash:  treeHash,
1650			Author:    sig,
1651			Committer: sig,
1652			Message:   message,
1653		}
1654	
1655		if parentHash != plumbing.ZeroHash {
1656			commit.ParentHashes = []plumbing.Hash{parentHash}
1657		}
1658	
1659		if err := SignCommitBestEffort(commit); err != nil {
1660			return plumbing.ZeroHash, fmt.Errorf("failed to sign commit: %w", err)
1661		}
1662	
1663		obj := repo.Storer.NewEncodedObject()
1664		if err := commit.Encode(obj); err != nil {
1665			return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
1666		}
1667	
1668		hash, err := repo.Storer.SetEncodedObject(obj)
1669		if err != nil {
1670			return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
1671		}
1672	
1673		return hash, nil
1674	}
