1676	// SignCommitBestEffort signs the commit using the registered ObjectSigner plugin.
1677	// If no signer is registered, the commit is left unsigned and no error is returned.
1678	func SignCommitBestEffort(commit *object.Commit) error {
1679		if !plugin.Has(plugin.ObjectSigner()) {
1680			return nil
1681		}
1682	
1683		signer, err := plugin.Get(plugin.ObjectSigner())
1684		if err != nil {
1685			return fmt.Errorf("getting object signer: %w", err)
1686		}
1687	
1688		if signer == nil {
1689			return nil
1690		}
1691	
1692		encoded := &plumbing.MemoryObject{}
1693		if err = commit.EncodeWithoutSignature(encoded); err != nil {
1694			return fmt.Errorf("encoding commit for signing: %w", err)
1695		}
1696	
1697		r, err := encoded.Reader()
1698		if err != nil {
1699			return fmt.Errorf("reading encoded commit: %w", err)
1700		}
1701	
1702		sig, err := signer.Sign(r)
1703		if err != nil {
1704			return fmt.Errorf("signing commit: %w", err)
1705		}
1706	
1707		commit.Signature = string(sig)
1708		return nil
1709	}
