306	// mergeRedaction merges redaction overrides into existing RedactionSettings.
307	// Only fields present in the override JSON are applied.
308	func mergeRedaction(dst *RedactionSettings, data json.RawMessage) error {
309		var raw map[string]json.RawMessage
310		if err := json.Unmarshal(data, &raw); err != nil {
311			return fmt.Errorf("parsing redaction: %w", err)
312		}
313		if piiRaw, ok := raw["pii"]; ok {
314			if dst.PII == nil {
315				dst.PII = &PIISettings{}
316			}
317			if err := mergePIISettings(dst.PII, piiRaw); err != nil {
318				return err
319			}
320		}
321		return nil
322	}
323	
324	// mergePIISettings merges PII overrides into existing PIISettings.
325	// Only fields present in the override JSON are applied; missing fields
326	// are preserved from the base settings.
327	func mergePIISettings(dst *PIISettings, data json.RawMessage) error {
328		var raw map[string]json.RawMessage
329		if err := json.Unmarshal(data, &raw); err != nil {
330			return fmt.Errorf("parsing pii: %w", err)
331		}
332		if v, ok := raw["enabled"]; ok {
333			if err := json.Unmarshal(v, &dst.Enabled); err != nil {
334				return fmt.Errorf("parsing pii.enabled: %w", err)
335			}
336		}
337		if v, ok := raw["email"]; ok {
338			var b bool
339			if err := json.Unmarshal(v, &b); err != nil {
340				return fmt.Errorf("parsing pii.email: %w", err)
341			}
342			dst.Email = &b
343		}
344		if v, ok := raw["phone"]; ok {
345			var b bool
346			if err := json.Unmarshal(v, &b); err != nil {
347				return fmt.Errorf("parsing pii.phone: %w", err)
348			}
349			dst.Phone = &b
350		}
351		if v, ok := raw["address"]; ok {
352			var b bool
353			if err := json.Unmarshal(v, &b); err != nil {
354				return fmt.Errorf("parsing pii.address: %w", err)
355			}
356			dst.Address = &b
357		}
358		if v, ok := raw["custom_patterns"]; ok {
359			var cp map[string]string
360			if err := json.Unmarshal(v, &cp); err != nil {
361				return fmt.Errorf("parsing pii.custom_patterns: %w", err)
362			}
363			if dst.CustomPatterns == nil {
364				dst.CustomPatterns = cp
365			} else {
366				for k, val := range cp {
367					dst.CustomPatterns[k] = val
368				}
369			}
370		}
371		return nil
372	}
