374	// IsSetUp returns true if Entire has been set up in the current repository.
375	// This checks if .entire/settings.json exists.
376	// Use this to avoid creating files/directories in repos where Entire was never enabled.
377	func IsSetUp(ctx context.Context) bool {
378		settingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsFile)
379		if err != nil {
380			return false
381		}
382		_, err = os.Stat(settingsFileAbs)
383		return err == nil
384	}
385	
386	// IsSetUpAny returns true if Entire has been set up in the current repository,
387	// checking both .entire/settings.json and .entire/settings.local.json.
388	// Use this to detect any prior setup, even if only local settings exist.
389	func IsSetUpAny(ctx context.Context) bool {
390		if IsSetUp(ctx) {
391			return true
392		}
393		localFileAbs, err := paths.AbsPath(ctx, EntireSettingsLocalFile)
394		if err != nil {
395			return false
396		}
397		_, err = os.Lstat(localFileAbs)
398		return err == nil
399	}
400	
401	// IsSetUpAndEnabled returns true if Entire is both set up and enabled.
402	// This checks if .entire/settings.json exists AND has enabled: true.
403	// Use this for hooks that should be no-ops when Entire is not active.
404	func IsSetUpAndEnabled(ctx context.Context) bool {
405		if !IsSetUp(ctx) {
406			return false
407		}
408		s, err := Load(ctx)
409		if err != nil {
410			return false
411		}
412		return s.Enabled
413	}
414	
415	// IsCheckpointsV2Enabled checks if checkpoints v2 is enabled in settings.
416	// Returns false by default if settings cannot be loaded or the key is missing.
417	func IsCheckpointsV2Enabled(ctx context.Context) bool {
418		settings, err := Load(ctx)
419		if err != nil {
420			return false
421		}
422		return settings.IsCheckpointsV2Enabled()
423	}
424	
425	// IsPushV2RefsEnabled checks if pushing v2 refs is enabled in settings.
426	// Returns false by default if settings cannot be loaded or flags are missing.
427	func IsPushV2RefsEnabled(ctx context.Context) bool {
428		s, err := Load(ctx)
429		if err != nil {
430			return false
431		}
432		return s.IsPushV2RefsEnabled()
433	}
434	
435	// IsFilteredFetchesEnabled checks if filtered fetches should be used.
436	// When enabled, filtered fetches always resolve remote names to URLs first so
437	// git does not persist promisor settings onto named remotes in local config.
438	// Returns false by default.
439	func IsFilteredFetchesEnabled(ctx context.Context) bool {
440		s, err := Load(ctx)
441		if err != nil {
442			return false
443		}
444		return s.IsFilteredFetchesEnabled()
