// SignCommitBestEffort signs the commit using the registered ObjectSigner plugin.
// If no signer is registered, signing is disabled via settings, or signing fails,
// the commit is left unsigned and the error is logged.
func SignCommitBestEffort(commit *object.Commit) {
	if !settings.IsSignCheckpointCommitsEnabled(context.Background()) {
		return
	}

	if !plugin.Has(plugin.ObjectSigner()) {
		return
	}

	signer, err := plugin.Get(plugin.ObjectSigner())
	if err != nil {
		slog.Warn("failed to get object signer", "error", err)
		return
	}

	if signer == nil {
		return
	}

	encoded := &plumbing.MemoryObject{}
	if err = commit.EncodeWithoutSignature(encoded); err != nil {
		slog.Warn("failed to encode commit for signing", "error", err)
		return
	}

	r, err := encoded.Reader()
	if err != nil {
		slog.Warn("failed to read encoded commit", "error", err)
		return
	}

	sig, err := signer.Sign(r)
	if err != nil {
		slog.Warn("failed to sign commit", "error", err)
		return
	}

	commit.Signature = string(sig)
}

